# swp-export-8q3
"""CSV export of orders."""
import csv
import io


def export_rows(rows, seen=None):
    seen = set() if seen is None else seen
    out = io.StringIO()
    writer = csv.writer(out)
    for row in rows:
        if tuple(row) not in seen:
            seen.add(tuple(row))
            writer.writerow(row)
    return out.getvalue()
